function PARTIAL_TWUALITY_POLYNOMIAL(E, F):
    n <- |E|
    c <- array of zeros indexed 0..n
    for each subset A of E:
        T <- symmetric_difference(F, A)   # F triangle A
        c[ |T| ] <- c[ |T| ] + 1
    return c            # equals (C(n,0), C(n,1), ..., C(n,n))

function IS_INTERPOLATING(c):
    support <- { k : c[k] > 0 }
    lo <- min(support);  hi <- max(support)
    for k from lo to hi:
        if c[k] = 0:
            return (False, gap_at=k)
    return (True, range=(lo, hi))
